"use client";

import { useEffect, useRef, useState, type ComponentProps, type MouseEvent } from "react";

import { IconBell } from "@rhs-ui/icons";
import {
  countText,
  DEFAULT_LABELS,
  fill,
  unreadSummary,
  type NotificationEntry,
  type NotificationLabels,
  type NotificationTime,
} from "@rhs-ui/application/notification-popover/notifications";
import { NotificationPanel } from "@rhs-ui/application/notification-popover/panel";
import { Button } from "@rhs-ui/primitives/button";
import { NotificationBadge } from "@rhs-ui/primitives/notification-badge";
import { Popover, PopoverContent, PopoverTrigger } from "@rhs-ui/primitives/popover";
import { cn } from "@/lib/utils";

export type { NotificationActor, NotificationEntry, NotificationLabels, NotificationTime } from "@rhs-ui/application/notification-popover/notifications";
export { NotificationPanel, type NotificationPanelProps } from "@rhs-ui/application/notification-popover/panel";

export interface NotificationPopoverProps extends Omit<ComponentProps<"div">, "children"> {
  /** The notifications, newest first: an id, a title, an optional body, a time, a link, whether it is unread, and who it came from. */
  items: readonly NotificationEntry[];
  /** How many are unread in all, when that is more than the list holds. It is the number on the bell. Default: the unread ones in `items`. */
  unreadCount?: number;
  /** Show skeleton rows in the panel while the notifications load. */
  loading?: boolean;
  /** The most rows the panel draws; the rest are behind "View all notifications". Default 8. */
  max?: number;
  /** Where "View all notifications" goes. Leave it out for no link. */
  viewAllHref?: string;
  /** A row was opened. The event comes with it, so a client-side router can call `preventDefault()`. The panel closes. */
  onOpenItem?: (item: NotificationEntry, event: MouseEvent<HTMLElement>) => void;
  /** An unread row was opened: mark it read. */
  onMarkRead?: (id: string) => void;
  /** Shows "Mark all as read" and runs this when it is pressed. */
  onMarkAllRead?: () => void;
  /** The moment the times are measured against. Pass it for relative text in server HTML, in tests and in previews; leave it out to use the browser's clock once the page is live. */
  now?: NotificationTime;
  /** The language of the words, the numbers and the dates. Default "en-US". */
  locale?: string;
  /** The time zone whose calendar days and clock the times use, so the server and the browser agree. Default "UTC". */
  timeZone?: string;
  /** Whether the panel is open, when you control it. */
  open?: boolean;
  /** Whether the panel is open to begin with. */
  defaultOpen?: boolean;
  /** Called when the panel opens or closes: by the bell, Escape, a click outside, or opening a row. */
  onOpenChange?: (open: boolean) => void;
  /** Which edge of the bell the panel lines up with. Default "end". */
  align?: "start" | "center" | "end";
  /** The words the bell and the panel say, for translation. */
  labels?: NotificationLabels;
}

/**
 * The bell in a header. A count sits on it (capped at 99+, and spoken as "Notifications, 3 unread"), and it opens a compact
 * panel of the newest notifications: unread ones marked with a dot and the word "Unread", "Mark all as read", and a link to
 * the full list. Opening a row marks it read and closes the panel, the arrow keys move between rows, and the panel says
 * "3 unread notifications" as it opens. While `loading` it draws skeleton rows; with nothing to show it says "You're all
 * caught up". Times are written from the `now` you pass, so the server and the browser agree.
 */
export function NotificationPopover({
  items,
  unreadCount,
  loading = false,
  max = 8,
  viewAllHref,
  onOpenItem,
  onMarkRead,
  onMarkAllRead,
  now,
  locale = "en-US",
  timeZone = "UTC",
  open,
  defaultOpen = false,
  onOpenChange,
  align = "end",
  labels,
  className,
  ...props
}: NotificationPopoverProps) {
  const words = { ...DEFAULT_LABELS, ...labels };
  const [ownOpen, setOwnOpen] = useState(defaultOpen);
  const [said, setSaid] = useState("");
  const content = useRef<HTMLDivElement>(null);
  const isOpen = open ?? ownOpen;
  // A panel that is open from the start (a preview, a first-run tip) never takes focus from the page: that is only for a panel somebody opened.
  const [wasOpen, setWasOpen] = useState(isOpen);
  const [fresh, setFresh] = useState(isOpen);
  if (isOpen !== wasOpen) {
    setWasOpen(isOpen);
    if (!isOpen) setFresh(false);
  }
  const unread = unreadCount ?? items.filter((item) => item.unread).length;
  const name = unread > 0 ? `${words.notifications}, ${fill(words.bellUnread, { count: countText(unread, locale) })}` : words.notifications;

  function setOpen(next: boolean) {
    if (open === undefined) setOwnOpen(next);
    onOpenChange?.(next);
  }

  // The live region lives on the bell, which is always there; the panel is not, and words that arrive together with their region are often not read.
  useEffect(() => {
    setSaid(isOpen ? (loading ? words.loading : unreadSummary(unread, locale, words)) : "");
  }, [isOpen, loading]);

  return (
    <div data-slot="notification-popover" className={cn("inline-flex", className)} {...props}>
      <Popover open={isOpen} onOpenChange={setOpen}>
        <PopoverTrigger asChild>
          <Button type="button" variant="ghost" size="icon" aria-label={name} className="text-muted-foreground hover:text-foreground aria-expanded:bg-muted aria-expanded:text-foreground">
            {/* The badge sits on the corner of the button, not on the bell, so the bell stays whole. */}
            <NotificationBadge label={words.notifications} count={unread} className="size-9 items-center justify-center">
              <IconBell className="size-[1.125rem]" />
            </NotificationBadge>
          </Button>
        </PopoverTrigger>
        <PopoverContent
          ref={content}
          align={align}
          collisionPadding={8}
          aria-label={words.notifications}
          onOpenAutoFocus={(event) => {
            // Focus goes to the first row, the one the arrow keys start from, and not to the header's button.
            event.preventDefault();
            if (fresh) return;
            const root = content.current;
            const first = root?.querySelector<HTMLElement>('[data-row][tabindex="0"]') ?? root?.querySelector<HTMLElement>("a[href], button:not([aria-disabled='true'])");
            (first ?? root)?.focus({ preventScroll: true });
          }}
          className="flex max-h-[min(32rem,var(--radix-popover-content-available-height))] w-[min(24rem,calc(100vw-1rem))] flex-col overflow-hidden p-0"
        >
          <NotificationPanel
            items={items}
            unreadCount={unreadCount}
            loading={loading}
            max={max}
            viewAllHref={viewAllHref}
            onOpenItem={onOpenItem}
            onMarkRead={onMarkRead}
            onMarkAllRead={
              onMarkAllRead
                ? () => {
                    onMarkAllRead();
                    setSaid(words.allMarked);
                  }
                : undefined
            }
            onNavigate={() => setOpen(false)}
            now={now}
            locale={locale}
            timeZone={timeZone}
            labels={labels}
            className="min-h-0 flex-1"
          />
        </PopoverContent>
      </Popover>
      <p role="status" aria-live="polite" className="sr-only">
        {said}
      </p>
    </div>
  );
}

"use client";

import { useEffect, useId, useState, type ComponentProps, type KeyboardEvent, type MouseEvent } from "react";

import { IconArrowRight, IconBell, IconCheck, IconCheckDouble } from "@rhs-ui/icons";
import {
  DEFAULT_LABELS,
  exactText,
  stampText,
  timeText,
  toTimestamp,
  type NotificationEntry,
  type NotificationLabels,
  type NotificationTime,
} from "@rhs-ui/application/notification-popover/notifications";
import { Avatar, AvatarFallback, AvatarImage, initialsOf } from "@rhs-ui/primitives/avatar";
import { Button, buttonVariants } from "@rhs-ui/primitives/button";
import { Skeleton } from "@rhs-ui/primitives/skeleton";
import { cn } from "@/lib/utils";

export interface NotificationPanelProps extends Omit<ComponentProps<"div">, "children"> {
  /** The notifications, newest first. Only the first `max` are drawn. */
  items: readonly NotificationEntry[];
  /** How many are unread in all, when that is more than what is loaded here. Default: the unread ones in `items`. */
  unreadCount?: number;
  /** Show skeleton rows in place of the list while the notifications load. */
  loading?: boolean;
  /** The most rows to draw. The rest are behind the link at the foot. Default 8. */
  max?: number;
  /** Where the link at the foot goes: the page with every notification. Leave it out for no link. */
  viewAllHref?: string;
  /** A row was opened. The event comes with it, so a client-side router can call `preventDefault()`. An unread row is marked read by `onMarkRead` straight after. */
  onOpenItem?: (item: NotificationEntry, event: MouseEvent<HTMLElement>) => void;
  /** An unread row was opened: mark it read. */
  onMarkRead?: (id: string) => void;
  /** Shows "Mark all as read" and runs this when it is pressed. */
  onMarkAllRead?: () => void;
  /** Called after a row or the link at the foot was used, so a popover around the panel can close. */
  onNavigate?: () => void;
  /** The moment the times are measured against. Leave it out to use the browser's clock once the page is live; pass it for relative text in server HTML, in tests and in previews. */
  now?: NotificationTime;
  /** The language of the words and the dates. Default "en-US". */
  locale?: string;
  /** The time zone whose calendar days and clock the times use, so the server and the browser agree. Default "UTC". */
  timeZone?: string;
  /** The words the panel says, for translation. */
  labels?: NotificationLabels;
}

/** The clock the times are read against: `now` when it is given, otherwise null until the browser has one, so the server and the first paint never disagree. */
function useClock(now: NotificationTime | undefined): number | null {
  const [tick, setTick] = useState<number | null>(null);
  const pinned = now !== undefined;
  useEffect(() => {
    if (!pinned) setTick(Date.now());
  }, [pinned]);
  if (pinned) {
    const at = toTimestamp(now);
    return Number.isNaN(at) ? tick : at;
  }
  return tick;
}

interface RowProps {
  item: NotificationEntry;
  index: number;
  active: boolean;
  clock: number | null;
  locale: string;
  timeZone: string;
  unreadWord: string;
  onActive: (index: number) => void;
  onOpen: (item: NotificationEntry, event: MouseEvent<HTMLElement>) => void;
}

function Row({ item, index, active, clock, locale, timeZone, unreadWord, onActive, onOpen }: RowProps) {
  const at = toTimestamp(item.time);
  const unread = item.unread === true;
  const shown = clock === null ? stampText(at, locale, timeZone) : timeText(at, clock, locale, timeZone);
  const shared = {
    "data-row": "",
    tabIndex: active ? 0 : -1,
    onFocus: () => onActive(index),
    onClick: (event: MouseEvent<HTMLElement>) => onOpen(item, event),
    className:
      "flex w-full items-start gap-3 py-3 pr-4 pl-5 text-left outline-none transition-colors duration-150 hover:bg-muted/70 focus-visible:bg-muted/70 focus-visible:ring-[3px] focus-visible:ring-inset focus-visible:ring-ring/40 motion-reduce:transition-none",
  } as const;
  const content = (
    <>
      {item.actor ? (
        <Avatar aria-hidden="true" className="ring-1 ring-border">
          {item.actor.image ? <AvatarImage src={item.actor.image} alt="" /> : null}
          <AvatarFallback>{initialsOf(item.actor.name)}</AvatarFallback>
        </Avatar>
      ) : (
        <span aria-hidden="true" className="grid size-9 shrink-0 place-items-center rounded-full bg-muted text-foreground ring-1 ring-border [&_svg]:size-4">
          {item.icon ?? <IconBell />}
        </span>
      )}
      <span className="grid min-w-0 flex-1 gap-0.5">
        {/* The row is named by what it shows: the word Unread, what happened, the line under it, and when. What is read out is what is seen, and what a voice control can say. */}
        <span className={cn("line-clamp-2 text-sm leading-snug [overflow-wrap:anywhere]", unread ? "font-semibold text-foreground" : "font-medium text-muted-foreground")}>
          {unread ? <span className="sr-only">{unreadWord}. </span> : null}
          {item.title}
        </span>
        <span className="grid gap-1">
          {item.body ? <span className="line-clamp-2 text-[0.8125rem] leading-snug text-muted-foreground [overflow-wrap:anywhere]">{item.body}</span> : null}
          <time dateTime={Number.isNaN(at) ? undefined : new Date(at).toISOString()} title={exactText(at, locale, timeZone)} className="text-xs text-muted-foreground tabular-nums">
            {shown}
          </time>
        </span>
      </span>
    </>
  );
  return (
    <li data-unread={unread || undefined} className={cn("relative", unread && "bg-muted/40")}>
      {/* In the gutter left of the avatar, centred on it, with air on both sides: the dot belongs to the row, not to the picture. */}
      {unread ? <span aria-hidden="true" className="pointer-events-none absolute top-[1.6875rem] left-2 z-10 size-1.5 rounded-full bg-foreground" /> : null}
      {item.href ? (
        <a href={item.href} {...shared}>
          {content}
        </a>
      ) : (
        <button type="button" {...shared}>
          {content}
        </button>
      )}
    </li>
  );
}

/**
 * The inside of the bell's popover, on its own: a header with "Mark all as read", the newest notifications, and a link to
 * the full list. Each row is one link (or button) with a dot and the word "Unread" for the ones not seen yet, and the
 * arrow keys, Home and End move between rows with only one of them in the tab order. While `loading` it draws skeleton
 * rows, with nothing to read yet it says "You're all caught up", and opening a row marks it read. Use it in a sheet on a
 * phone, or let NotificationPopover put it under the bell.
 */
export function NotificationPanel({
  items,
  unreadCount,
  loading = false,
  max = 8,
  viewAllHref,
  onOpenItem,
  onMarkRead,
  onMarkAllRead,
  onNavigate,
  now,
  locale = "en-US",
  timeZone = "UTC",
  labels,
  className,
  ...props
}: NotificationPanelProps) {
  const words = { ...DEFAULT_LABELS, ...labels };
  const id = useId();
  const clock = useClock(now);
  const [active, setActive] = useState(0);
  const rows = items.slice(0, Math.max(0, max));
  const unread = unreadCount ?? items.filter((item) => item.unread).length;
  const current = Math.min(active, Math.max(0, rows.length - 1));

  function open(item: NotificationEntry, event: MouseEvent<HTMLElement>) {
    onOpenItem?.(item, event);
    if (item.unread) onMarkRead?.(item.id);
    onNavigate?.();
  }

  function move(event: KeyboardEvent<HTMLUListElement>) {
    if (!["ArrowDown", "ArrowUp", "Home", "End"].includes(event.key)) return;
    const list = [...event.currentTarget.querySelectorAll<HTMLElement>("[data-row]")];
    const at = list.findIndex((row) => row === document.activeElement);
    const target = event.key === "Home" ? 0 : event.key === "End" ? list.length - 1 : Math.min(list.length - 1, Math.max(0, at + (event.key === "ArrowDown" ? 1 : -1)));
    event.preventDefault();
    list[target]?.focus();
  }

  return (
    // A group, not a section: inside a popover (which is already a named dialog) or a sheet, a second landmark would only be noise.
    <div role="group" data-slot="notification-panel" aria-labelledby={`${id}-title`} aria-busy={loading || undefined} className={cn("flex min-h-0 flex-col bg-popover text-popover-foreground", className)} {...props}>
      <div className="flex shrink-0 items-center justify-between gap-3 border-b border-border px-4 py-2.5">
        <h2 id={`${id}-title`} className="text-sm font-semibold tracking-[-0.01em]">
          {words.notifications}
        </h2>
        {onMarkAllRead ? (
          // aria-disabled and not disabled: a button that disables itself under the finger would drop keyboard focus to the page.
          <Button
            type="button"
            variant="ghost"
            size="sm"
            aria-disabled={unread === 0 || loading}
            className="-mr-1.5 aria-disabled:pointer-events-none aria-disabled:opacity-50"
            onClick={() => {
              if (unread > 0 && !loading) onMarkAllRead();
            }}
          >
            <IconCheckDouble />
            {words.markAll}
          </Button>
        ) : null}
      </div>

      {loading ? (
        <div className="min-h-0 flex-1">
          <p role="status" className="sr-only">
            {words.loading}
          </p>
          <ul aria-hidden="true" className="divide-y divide-border">
            {[0, 1, 2].map((row) => (
              <li key={row} className="flex items-start gap-3 py-3 pr-4 pl-5">
                <Skeleton delay={row * 120} className="size-9 shrink-0 rounded-full" />
                <div className="grid flex-1 gap-2 pt-1">
                  <Skeleton delay={row * 120 + 60} className="h-3.5 w-4/5" />
                  <Skeleton delay={row * 120 + 120} className="h-3 w-full" />
                  <Skeleton delay={row * 120 + 180} className="h-3 w-12" />
                </div>
              </li>
            ))}
          </ul>
        </div>
      ) : rows.length === 0 ? (
        <div className="flex flex-1 flex-col items-center gap-1 px-6 py-12 text-center">
          <span aria-hidden="true" className="mb-3 grid size-10 place-items-center rounded-full border border-border bg-muted text-foreground">
            <IconCheck className="size-[1.125rem]" />
          </span>
          <p className="text-sm font-medium">{words.caughtUp}</p>
          <p className="max-w-[16rem] text-[0.8125rem] leading-relaxed text-muted-foreground">{words.caughtUpBody}</p>
        </div>
      ) : (
        <ul onKeyDown={move} className="relative min-h-0 flex-1 divide-y divide-border overflow-y-auto overscroll-contain">
          {rows.map((item, index) => (
            <Row key={item.id} item={item} index={index} active={index === current} clock={clock} locale={locale} timeZone={timeZone} unreadWord={words.unread} onActive={setActive} onOpen={open} />
          ))}
        </ul>
      )}

      {viewAllHref ? (
        <div className="shrink-0 border-t border-border bg-muted/30 p-1.5">
          <a href={viewAllHref} onClick={() => onNavigate?.()} className={cn(buttonVariants({ variant: "ghost", size: "sm" }), "w-full justify-center")}>
            {words.viewAll}
            <IconArrowRight />
          </a>
        </div>
      ) : null}
    </div>
  );
}

import type { ReactNode } from "react";

/** A moment: a Date, an ISO string or a timestamp in milliseconds. */
export type NotificationTime = Date | string | number;

/** The person behind a notification. */
export interface NotificationActor {
  /** Their name. Initials stand in while the picture loads, or when there is none. */
  name: string;
  /** A picture. */
  image?: string;
}

/** One notification in the panel. */
export interface NotificationEntry {
  /** A stable identity: it is what `onMarkRead` receives, and the key of the row. */
  id: string;
  /** What happened, in a sentence: "Mara Okafor replied to your comment". */
  title: string;
  /** A line of context under it, such as the comment itself. Clamped to two lines. */
  body?: string;
  /** When it happened. Read as relative words ("4 min. ago"), with the exact moment in the row's title. */
  time: NotificationTime;
  /** Where the row goes. Without it the row is a button, and `onOpenItem` says what it does. */
  href?: string;
  /** Not seen yet: the row gets a dot, a heavier title and the word "Unread" for screen readers. */
  unread?: boolean;
  /** Who it came from. Without one the row shows `icon` instead of a picture. */
  actor?: NotificationActor;
  /** An icon element, drawn at 16px in a quiet tile, for a notification that no person sent: an export, a payment, a release. A bell stands in when there is none. */
  icon?: ReactNode;
}

/** The words the bell and the panel say, for translation. `{count}` is a number, written in the locale. */
export interface NotificationLabels {
  /** The bell's name, and the panel's. Default "Notifications". */
  notifications?: string;
  /** Said after the bell's name while something is unread. Default "{count} unread". */
  bellUnread?: string;
  /** Said when the panel opens, for one unread notification. Default "{count} unread notification". */
  unreadOne?: string;
  /** Said when the panel opens, for several. Default "{count} unread notifications". */
  unreadMany?: string;
  /** Read before an unread row, next to the dot. Default "Unread". */
  unread?: string;
  /** The button that clears every dot. Default "Mark all as read". */
  markAll?: string;
  /** Said once they are all read. Default "All notifications marked as read". */
  allMarked?: string;
  /** The title of the empty state. Default "You're all caught up". */
  caughtUp?: string;
  /** The line under it. Default "New notifications will show up here." */
  caughtUpBody?: string;
  /** Said while the skeleton rows show. Default "Loading notifications". */
  loading?: string;
  /** The link at the foot of the panel. Default "View all notifications". */
  viewAll?: string;
}

export const DEFAULT_LABELS = {
  notifications: "Notifications",
  bellUnread: "{count} unread",
  unreadOne: "{count} unread notification",
  unreadMany: "{count} unread notifications",
  unread: "Unread",
  markAll: "Mark all as read",
  allMarked: "All notifications marked as read",
  caughtUp: "You're all caught up",
  caughtUpBody: "New notifications will show up here.",
  loading: "Loading notifications",
  viewAll: "View all notifications",
} satisfies Required<NotificationLabels>;

/** Puts values into a template: `fill("{count} unread", { count: 3 })`. A name it does not know is left as it was. */
export function fill(template: string, values: Record<string, string | number>): string {
  return template.replace(/\{(\w+)\}/g, (match, key: string) => (key in values ? String(values[key]) : match));
}

/** `one` for 1 in the locale's own rules, `other` for the rest. */
export function plural(count: number, one: string, other: string, locale: string): string {
  try {
    return new Intl.PluralRules(locale).select(count) === "one" ? one : other;
  } catch {
    return count === 1 ? one : other;
  }
}

/** A count as the bell and the panel say it: written in the locale, and "99+" past 99. */
export function countText(count: number, locale: string): string {
  const format = (value: number) => {
    try {
      return new Intl.NumberFormat(locale).format(value);
    } catch {
      return String(value);
    }
  };
  return count > 99 ? `${format(99)}+` : format(count);
}

const MINUTE = 60_000;
const HOUR = 3_600_000;
const DAY = 86_400_000;

/** A moment as milliseconds, or NaN when it is not a date at all. */
export function toTimestamp(time: NotificationTime): number {
  return new Date(time).getTime();
}

function dateFormat(locale: string, timeZone: string, options: Intl.DateTimeFormatOptions): Intl.DateTimeFormat {
  try {
    return new Intl.DateTimeFormat(locale, { ...options, timeZone });
  } catch {
    // An unknown locale or time zone must not take the page down.
    return new Intl.DateTimeFormat("en-US", { ...options, timeZone: "UTC" });
  }
}

/** The calendar day a moment falls on in the zone, as a day number, so "yesterday" is the day before and not 24 hours ago. */
function dayNumber(at: number, timeZone: string): number {
  const parts = dateFormat("en-US", timeZone, { year: "numeric", month: "numeric", day: "numeric" }).formatToParts(at);
  const part = (type: string) => Number(parts.find((entry) => entry.type === type)?.value);
  return Math.floor(Date.UTC(part("year"), part("month") - 1, part("day")) / DAY);
}

/**
 * How long ago, in short words: "now", "4 min. ago", "3 hr. ago", "yesterday", "3 days ago", and from a week on the date. The
 * words come from the locale, and the days from the calendar of the time zone, so the server and the browser write the same
 * text from the same `now`.
 */
export function timeText(at: number, now: number, locale: string, timeZone: string): string {
  if (Number.isNaN(at)) return "";
  const diff = at - now;
  const age = Math.abs(diff);
  let words: Intl.RelativeTimeFormat;
  try {
    words = new Intl.RelativeTimeFormat(locale, { numeric: "auto", style: "short" });
  } catch {
    words = new Intl.RelativeTimeFormat("en-US", { numeric: "auto", style: "short" });
  }
  if (age < MINUTE) return words.format(0, "second");
  if (age < HOUR) return words.format(Math.trunc(diff / MINUTE), "minute");
  if (age < DAY) return words.format(Math.trunc(diff / HOUR), "hour");
  const days = dayNumber(at, timeZone) - dayNumber(now, timeZone);
  if (Math.abs(days) < 7) return words.format(days, "day");
  const sameYear = dateFormat("en-US", timeZone, { year: "numeric" }).format(at) === dateFormat("en-US", timeZone, { year: "numeric" }).format(now);
  return dateFormat(locale, timeZone, { day: "numeric", month: "short", ...(sameYear ? {} : { year: "numeric" }) }).format(at);
}

/** The date and time written out, which is what the first paint shows before the browser's clock is known. */
export function stampText(at: number, locale: string, timeZone: string): string {
  return Number.isNaN(at) ? "" : dateFormat(locale, timeZone, { day: "numeric", month: "short", year: "numeric", hour: "numeric", minute: "2-digit" }).format(at);
}

/** The exact moment with its zone, for the row's title: "Tue, Nov 10, 2026, 9:12 AM UTC". */
export function exactText(at: number, locale: string, timeZone: string): string {
  return Number.isNaN(at) ? "" : dateFormat(locale, timeZone, { weekday: "short", day: "numeric", month: "short", year: "numeric", hour: "numeric", minute: "2-digit", timeZoneName: "short" }).format(at);
}

/** What the bell announces when the panel opens: "3 unread notifications", or that there is nothing new. */
export function unreadSummary(unread: number, locale: string, labels: Required<NotificationLabels>): string {
  return unread > 0 ? fill(plural(unread, labels.unreadOne, labels.unreadMany, locale), { count: countText(unread, locale) }) : labels.caughtUp;
}
